#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Enemies
{
    /// <summary>
    /// 舞王的动画行为：出场冲刺阶段（还没开始第一次跳舞），
    /// 在行走等动画之上叠加 slicestep（太空步）动画（Special 层，SpecialState = 1）。
    /// 冲到目标位置或撞到器械后 StartFirstDance 会设置跳舞计时器，
    /// 计时器非空时不再叠加，Special 层自动切回 None → 动画停止。
    /// </summary>
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.dancingZombie_Animation)]
    public class DancingZombie_AnimationBehaviour : HumanoidAnimationBehaviour
    {
        public DancingZombie_AnimationBehaviour(string nsp, string name) : base(nsp, name)
        {
        }
        protected override void ModifyAnimationParameters(Entity entity, int state, ref AnimationParameters parameters)
        {
            base.ModifyAnimationParameters(entity, state, ref parameters);
            if (!entity.IsDead
                && DancingZombie.GetStage(entity) == DancingZombie.STAGE_INTRO
                && DancingZombie.GetDanceTimer(entity) == null)
            {
                parameters.specialState = SPECIAL_STATE_SLICESTEP;
            }
        }
        public const int SPECIAL_STATE_SLICESTEP = 1;
    }
}
